package com.smartmanager.nativeapp;
import java.nio.charset.StandardCharsets;import java.util.*;
/** Versioned multi-batch payload. Invalid records are rejected, never discarded. */
public final class BatchArchive { private final LinkedHashMap<String,String> entries=new LinkedHashMap<>(); public void put(String id,String value){if(id==null||id.isEmpty()||value==null)throw new IllegalArgumentException("invalid batch");if(entries.containsKey(id))throw new IllegalArgumentException("duplicate batch");entries.put(id,value);} public void replace(String id,String value){if(!entries.containsKey(id))throw new IllegalArgumentException("unknown batch");entries.put(id,value);} public String get(String id){return entries.get(id);} public Set<String> ids(){return Collections.unmodifiableSet(entries.keySet());} public String encode(){StringBuilder b=new StringBuilder("BATCH-ARCHIVE-1\n");for(Map.Entry<String,String> e:entries.entrySet())b.append(enc(e.getKey())).append('.').append(enc(e.getValue())).append('\n');return b.toString();} public static BatchArchive decode(String raw){if(raw==null||!raw.startsWith("BATCH-ARCHIVE-1\n"))throw new IllegalArgumentException("invalid batch archive");BatchArchive a=new BatchArchive();for(String line:raw.substring(16).split("\\n")){if(line.isEmpty())continue;String[] p=line.split("\\.",2);if(p.length!=2)throw new IllegalArgumentException("corrupt batch archive");a.put(dec(p[0]),dec(p[1]));}return a;} private static String enc(String s){return java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8));} private static String dec(String s){return new String(java.util.Base64.getUrlDecoder().decode(s),StandardCharsets.UTF_8);} }
